import { writeFileSync } from 'fs';
import { join } from 'path';
import { DIST, DOMAIN, renderPage, ensureDir } from './core.js';

export function buildKitchenTools() {
  const calcDir = join(DIST, 'calc');
  ensureDir(calcDir);

  function renderKitchenPage(opts) {
    let visibleFaqHtml = '';
    if (opts.faq && opts.faq.length > 0) {
      visibleFaqHtml = `
        <div class="wb-card" style="margin-top:2.5rem; background:var(--surface); border:1px solid var(--border); padding:1.5rem; border-radius:8px;">
          <h2 style="font-family:var(--serif); font-size:1.4rem; margin-bottom:1.25rem;">Frequently Asked Questions</h2>
          ${opts.faq.map(f => `
            <div class="faq-item" style="border-bottom:1px solid var(--border); padding:0.85rem 0;" onclick="this.classList.toggle('open')">
              <div style="font-weight:600; cursor:pointer; display:flex; justify-content:space-between; align-items:center;">
                <span style="font-size:1rem;">${f.q}</span>
                <span class="faq-icon" style="font-size:1.2rem; transition:transform 0.2s; color:var(--text-muted);">+</span>
              </div>
              <div class="faq-answer" style="display:none; margin-top:0.6rem; color:var(--text-muted); font-size:0.92rem; line-height:1.65;">
                ${f.a}
              </div>
            </div>
          `).join('')}
        </div>
      `;
    }
    const fullBody = opts.bodyContent + visibleFaqHtml + `
      <style>
        .faq-item.open .faq-answer { display: block !important; }
        .faq-item.open .faq-icon { transform: rotate(45deg); color: #10b981; }
        .trap-card {
          background: var(--surface);
          border: 1px solid var(--border);
          border-radius: 6px;
          padding: 1.15rem;
          margin-bottom: 1rem;
          font-size: 0.92rem;
          line-height: 1.6;
        }
        .trap-card strong {
          display: block;
          margin-bottom: 0.35rem;
          font-size: 1rem;
        }
      </style>
    `;
    return renderPage({
      ...opts,
      bodyContent: fullBody
    });
  }


  // ─────────────────────────────────────────────────────────────────────────────
  // 1. GRAMS TO CUPS BY INGREDIENT
  // ─────────────────────────────────────────────────────────────────────────────
  const gramsToCupsBody = "\n    <div class=\"article-container\" style=\"max-width: 950px;\">\n      <nav style=\"font-family: var(--mono); font-size: 0.8rem; margin-bottom: 1.5rem; color: var(--text-muted);\">\n        <a href=\"/\">Home</a> &gt; <a href=\"/calc/\">Calculators</a> &gt; Grams to Cups\n      </nav>\n\n      <header style=\"margin-bottom: 2rem;\">\n        <h1 style=\"font-family: var(--serif); font-size: 2.2rem; margin-bottom: 0.5rem;\">Grams to Cups Converter (By Ingredient & Standard)</h1>\n        <p style=\"color: var(--text-muted); font-size: 1.05rem; line-height: 1.6;\">\n          Convert culinary weight (grams) to kitchen volume (cups, tablespoons, teaspoons) with USDA density factors, chef cooking fractions, interactive measuring cup visualizer, and international cup calibration.\n        </p>\n      </header>\n\n      <!-- Key Callout -->\n      <div style=\"background: var(--surface-alt); border-left: 4px solid var(--border-strong); padding: 0.85rem 1.15rem; margin-bottom: 1.5rem; font-size: 0.95rem; font-family: var(--serif);\">\n        <strong>Why 1 Cup is Never Just \"1 Cup\":</strong> Cups measure <em>volume</em>, while grams measure <em>mass</em>. One cup of all-purpose flour weighs <strong>120 grams</strong>, granulated sugar weighs <strong>200 grams</strong>, and butter weighs <strong>227 grams</strong>. Furthermore, a US Customary Cup (236.6 mL) differs from a Metric Cup (250 mL). Select your exact ingredient and cup standard below!\n      </div>\n\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1.5rem; margin-bottom: 2rem;\">\n        <!-- Input Card -->\n        <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px;\">\n          <h3 style=\"font-family: var(--serif); font-size: 1.2rem; margin-bottom: 1.25rem; color: var(--fg);\">Weight & Ingredient</h3>\n\n          <div style=\"margin-bottom: 1.25rem;\">\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Select Ingredient</label>\n            <select id=\"ingredientSelect\" onchange=\"calcGramsToCups()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--sans); border-radius: 4px; font-size: 0.95rem;\">\n              \n              <optgroup label=\"Flours & Powders\">\n                <option value=\"120|All-Purpose Flour (Spooned & Leveled)|0.507\" selected>All-Purpose Flour (Spooned & Leveled) - 120g</option>\n                <option value=\"145|All-Purpose Flour (Dipped / Packed)|0.613\">All-Purpose Flour (Dipped / Packed) - 145g</option>\n                <option value=\"127|Bread Flour|0.537\">Bread Flour - 127g</option>\n                <option value=\"130|Whole Wheat Flour|0.549\">Whole Wheat Flour - 130g</option>\n                <option value=\"114|Cake Flour (Sifted)|0.482\">Cake Flour (Sifted) - 114g</option>\n                <option value=\"96|Almond Flour (Blanched)|0.406\">Almond Flour (Blanched) - 96g</option>\n                <option value=\"112|Coconut Flour|0.473\">Coconut Flour - 112g</option>\n                <option value=\"128|Cornstarch|0.541\">Cornstarch - 128g</option>\n                <option value=\"85|Cocoa Powder (Unsweetened)|0.359\">Cocoa Powder (Unsweetened) - 85g</option>\n                <option value=\"192|Baking Powder|0.812\">Baking Powder - 192g</option>\n                <option value=\"220|Baking Soda|0.930\">Baking Soda - 220g</option>\n              </optgroup>\n              <optgroup label=\"Sugars & Sweeteners\">\n                <option value=\"200|Granulated White Sugar|0.845\">Granulated White Sugar - 200g</option>\n                <option value=\"220|Brown Sugar (Firmly Packed)|0.930\">Brown Sugar (Firmly Packed) - 220g</option>\n                <option value=\"145|Brown Sugar (Loose / Unpacked)|0.613\">Brown Sugar (Loose / Unpacked) - 145g</option>\n                <option value=\"100|Powdered / Icing Sugar (Sifted)|0.423\">Powdered / Icing Sugar (Sifted) - 100g</option>\n                <option value=\"125|Powdered Sugar (Unsifted)|0.528\">Powdered Sugar (Unsifted) - 125g</option>\n                <option value=\"340|Honey / Molasses|1.437\">Honey / Molasses - 340g</option>\n                <option value=\"312|Pure Maple Syrup|1.319\">Pure Maple Syrup - 312g</option>\n              </optgroup>\n              <optgroup label=\"Dairy, Fats & Liquids\">\n                <option value=\"227|Butter (Unsalted/Salted - 2 Sticks)|0.959\">Butter (2 Sticks = 1 Cup) - 227g</option>\n                <option value=\"218|Vegetable / Canola Oil|0.921\">Vegetable / Canola Oil - 218g</option>\n                <option value=\"216|Olive Oil|0.913\">Olive Oil - 216g</option>\n                <option value=\"244|Whole Milk|1.031\">Whole Milk - 244g</option>\n                <option value=\"238|Heavy Whipping Cream|1.006\">Heavy Whipping Cream - 238g</option>\n                <option value=\"240|Sour Cream / Greek Yogurt|1.014\">Sour Cream / Greek Yogurt - 240g</option>\n                <option value=\"270|Peanut Butter (Smooth)|1.141\">Peanut Butter (Smooth) - 270g</option>\n                <option value=\"237|Water (Pure)|1.000\">Water - 237g (236.6 mL)</option>\n              </optgroup>\n              <optgroup label=\"Grains, Seeds & Dry Goods\">\n                <option value=\"90|Rolled Oats (Old Fashioned)|0.380\">Rolled Oats (Old Fashioned) - 90g</option>\n                <option value=\"80|Quick Oats|0.338\">Quick Oats - 80g</option>\n                <option value=\"160|Steel Cut Oats|0.676\">Steel Cut Oats - 160g</option>\n                <option value=\"185|White Rice (Uncooked Long-Grain)|0.782\">White Rice (Uncooked) - 185g</option>\n                <option value=\"190|Brown Rice (Uncooked)|0.803\">Brown Rice (Uncooked) - 190g</option>\n                <option value=\"170|Quinoa (Uncooked)|0.719\">Quinoa (Uncooked) - 170g</option>\n                <option value=\"112|Breadcrumbs (Dry)|0.473\">Breadcrumbs (Dry) - 112g</option>\n              </optgroup>\n              <optgroup label=\"Salts\">\n                <option value=\"288|Table Salt (Fine)|1.217\">Table Salt (Fine) - 288g</option>\n                <option value=\"240|Morton Kosher Salt|1.014\">Morton Kosher Salt - 240g</option>\n                <option value=\"144|Diamond Crystal Kosher Salt|0.609\">Diamond Crystal Kosher Salt - 144g</option>\n              </optgroup>\n              <optgroup label=\"Mix-ins & Nuts\">\n                <option value=\"170|Chocolate Chips (Semi-Sweet)|0.719\">Chocolate Chips (Semi-Sweet) - 170g</option>\n                <option value=\"115|Walnuts / Pecans (Chopped)|0.486\">Walnuts / Pecans (Chopped) - 115g</option>\n                <option value=\"150|Raisins (Seedless)|0.634\">Raisins (Seedless) - 150g</option>\n              </optgroup>\n  \n            </select>\n          </div>\n\n          <div style=\"margin-bottom: 1.25rem;\">\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Weight in Grams (g)</label>\n            <input type=\"number\" id=\"gramsInput\" value=\"120\" min=\"0.1\" step=\"any\" oninput=\"calcGramsToCups()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--mono); font-size: 1.15rem; border-radius: 4px;\">\n            <div style=\"display: flex; gap: 0.35rem; margin-top: 0.5rem; flex-wrap: wrap;\">\n              <button type=\"button\" onclick=\"setGrams(30)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">30g</button>\n              <button type=\"button\" onclick=\"setGrams(50)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">50g</button>\n              <button type=\"button\" onclick=\"setGrams(100)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">100g</button>\n              <button type=\"button\" onclick=\"setGrams(120)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">120g</button>\n              <button type=\"button\" onclick=\"setGrams(150)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">150g</button>\n              <button type=\"button\" onclick=\"setGrams(200)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">200g</button>\n              <button type=\"button\" onclick=\"setGrams(250)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">250g</button>\n              <button type=\"button\" onclick=\"setGrams(500)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">500g</button>\n            </div>\n          </div>\n\n          <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; margin-bottom: 1.25rem;\">\n            <div>\n              <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Cup Standard</label>\n              <select id=\"cupStandardSelect\" onchange=\"calcGramsToCups()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--sans); border-radius: 4px; font-size: 0.85rem;\">\n                <option value=\"236.588|US Customary (236.6 mL)\" selected>US Customary (236.6 mL)</option>\n                <option value=\"240.000|US Legal / Nutrition (240.0 mL)\">US Legal (240.0 mL)</option>\n                <option value=\"250.000|Metric Cup (250.0 mL - UK/AU/NZ)\">Metric Cup (250.0 mL)</option>\n                <option value=\"284.130|Imperial Cup (284.1 mL - Traditional UK)\">Imperial Cup (284.1 mL)</option>\n              </select>\n            </div>\n\n            <div>\n              <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Batch Multiplier</label>\n              <select id=\"batchMultiplier\" onchange=\"calcGramsToCups()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--sans); border-radius: 4px; font-size: 0.85rem;\">\n                <option value=\"0.5\">0.5× (Half Batch)</option>\n                <option value=\"1\" selected>1× (Standard Recipe)</option>\n                <option value=\"1.5\">1.5× (1.5× Recipe)</option>\n                <option value=\"2\">2× (Double Batch)</option>\n                <option value=\"3\">3× (Triple Batch)</option>\n              </select>\n            </div>\n          </div>\n\n          <div style=\"font-family: var(--mono); font-size: 0.78rem; color: var(--text-muted); padding: 0.5rem; background: var(--surface-alt); border-radius: 4px; display: flex; justify-content: space-between;\">\n            <span>Ingredient Density:</span>\n            <span id=\"densityBadge\" style=\"font-weight: bold; color: var(--fg);\">-- g/mL</span>\n          </div>\n        </div>\n\n        <!-- Visual & Results Card -->\n        <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; display: flex; flex-direction: column; justify-content: space-between;\">\n          <div>\n            <h3 style=\"font-family: var(--serif); font-size: 1.2rem; margin-bottom: 1rem; color: var(--fg);\">Volume & Practical Kitchen Measures</h3>\n            <div id=\"cupResults\" style=\"display: flex; flex-direction: column; gap: 0.75rem;\">\n              <!-- Populated by JS -->\n            </div>\n          </div>\n\n          <!-- Pure SVG Measuring Cup Visualizer -->\n          <div style=\"margin-top: 1.25rem; padding-top: 1rem; border-top: 1px solid var(--border);\">\n            <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem;\">\n              <span style=\"font-family: var(--mono); font-size: 0.75rem; text-transform: uppercase; color: var(--text-muted);\">Measuring Cup Fill Gauge</span>\n              <span id=\"cupFillBadge\" style=\"font-family: var(--mono); font-size: 0.75rem; color: #10b981; font-weight: bold;\">1.00 Cup</span>\n            </div>\n            <div id=\"cupSvgContainer\">\n              <!-- SVG drawn by JS -->\n            </div>\n          </div>\n\n          <div style=\"margin-top: 1rem;\">\n            <button type=\"button\" id=\"copyBakingBtn\" onclick=\"copyBakingTakeoff()\" class=\"btn\" style=\"width: 100%; padding: 0.65rem; font-family: var(--mono); font-size: 0.85rem; font-weight: bold; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); border-radius: 4px; cursor: pointer; transition: all 0.2s;\">\n              📋 Copy Recipe Measurement Line\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Step-by-Step Mathematical & Physical Derivation -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin: 0 0 0.75rem; color: var(--fg);\">📐 Physical Density & Volume Derivation</h3>\n        <p style=\"font-size: 0.95rem; line-height: 1.6; color: var(--text-muted); margin-bottom: 1rem;\">\n          How digital kitchen scales and volume measuring tools interact mathematically through physical bulk density:\n        </p>\n        <div id=\"derivationFormula\" style=\"font-family: var(--mono); font-size: 0.85rem; line-height: 1.8; background: var(--surface-alt); padding: 1rem; border-radius: 4px; border: 1px solid var(--border);\">\n          <!-- Injected dynamically -->\n        </div>\n      </div>\n\n      <!-- 5 Fatal Pitfalls Section -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin-top: 0; margin-bottom: 0.75rem; color: var(--fg);\">⚠️ 5 Fatal Baking Pitfalls & Volumetric Measurement Traps</h3>\n        <p style=\"color: var(--text-muted); font-size: 0.95rem; line-height: 1.6; margin-bottom: 1.25rem;\">\n          Baking is strict chemical engineering. In chemistry, small volumetric deviations spoil pH, gluten hydration, and steam leavening. Avoid these 5 traps:\n        </p>\n\n        <div style=\"display: grid; gap: 1rem;\">\n          <div class=\"trap-card\" style=\"border-left: 4px solid #ef4444;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">1. Converting Flour Without Knowing Aeration / Packing State</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Dipping a measuring cup directly into a bag of flour compacts the grain. A cup dipped and leveled weighs <strong>140g to 155g</strong>, whereas properly aerated flour (spooned into the cup and leveled) weighs <strong>120g</strong>. That extra 25g to 35g of flour per cup absorbs excessive liquid, turning tender cakes rubbery and artisan breads dense and dry.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #f59e0b;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">2. The Diamond Crystal vs Morton Kosher Salt Discrepancy</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Diamond Crystal kosher salt has hollow flaky crystals weighing only <strong>144g per cup</strong> (2.8g per tsp), whereas Morton kosher salt is dense rolled crystals weighing <strong>240g per cup</strong> (4.8g per tsp). Substituting Morton 1:1 by volume for Diamond Crystal makes your food nearly <strong>70% saltier</strong> than intended.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #10b981;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">3. The International Cup Volume Chasm (US vs Metric vs Imperial)</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              A US Customary cup holds <strong>236.6 mL</strong> (8 fluid ounces), a US Legal nutrition cup holds <strong>240.0 mL</strong>, an Australian / New Zealand / UK Metric cup holds <strong>250.0 mL</strong>, and an archaic Imperial British cup holds <strong>284.1 mL</strong>. Baking a British or Australian recipe using an American cup creates a 5.7% to 20% shortage of flour and sugar.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #3b82f6;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">4. The Brown Sugar Entrapped Air Trap (Packed vs Loose)</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Brown sugar contains sticky molasses that traps massive air pockets when scooped loosely, yielding only ~145g per cup. Standard baking recipes universally assume <strong>firmly packed brown sugar</strong> (pressed into the cup until it holds its shape like a sandcastle), which weighs <strong>220g per cup</strong>. Scooping loosely causes a disastrous 34% sugar deficit.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #8b5cf6;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">5. Fluid Ounces (Volume) vs Avoirdupois Ounces (Weight) Confusion</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              A \"fluid ounce\" is a unit of volume ($29.57\\text{ mL}$), while an ounce is a unit of mass ($28.35\\text{ g}$). Water is the only culinary substance where $1\\text{ fl oz} \\approx 1\\text{ oz}$ mass. For dense honey, an 8 fl oz cup weighs over <strong>11.5 dry ounces (340 grams)</strong>. Weighing honey to \"8 ounces\" on a scale results in a 30% shortage.\n            </p>\n          </div>\n        </div>\n      </div>\n\n      <!-- Master Reference Table -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin-top: 0; margin-bottom: 1rem; color: var(--fg);\">📋 Master Baking Conversion Table (US Customary Cups to Grams)</h3>\n        <div style=\"overflow-x: auto;\">\n          <table style=\"width: 100%; border-collapse: collapse; font-family: var(--sans); font-size: 0.85rem; text-align: left;\">\n            <thead>\n              <tr style=\"background: var(--surface-alt); border-bottom: 2px solid var(--border);\">\n                <th style=\"padding: 0.55rem 0.75rem;\">Ingredient</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">1/4 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">1/3 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">1/2 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">3/4 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem; color: #10b981;\">1 Cup</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">All-Purpose Flour (Spooned & Leveled)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">30g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">40g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">60g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">90g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">120g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Bread Flour</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">31.8g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">42.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">63.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">95.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">127g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Granulated White Sugar</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">50g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">66.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">100g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">150g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">200g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Brown Sugar (Packed)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">55g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">73.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">110g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">165g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">220g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Powdered Sugar (Sifted)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">25g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">33.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">50g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">75g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">100g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Butter (1 stick = 1/2 cup)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">56.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">75.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">113.4g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">170.1g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">227g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Vegetable / Canola Oil</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">54.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">72.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">109g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">163.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">218g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Rolled Oats</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">22.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">30g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">45g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">67.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">90g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Cocoa Powder (Unsweetened)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">21.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">28.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">42.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">63.8g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">85g</td></tr>\n              <tr><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Chocolate Chips (Semi-Sweet)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">42.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">56.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">85g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">127.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">170g</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n\n    <script>\n      var currentConversionData = null;\n\n      function setGrams(val) {\n        document.getElementById('gramsInput').value = val;\n        calcGramsToCups();\n      }\n\n      function calcGramsToCups() {\n        var baseGrams = parseFloat(document.getElementById('gramsInput').value) || 0;\n        var multiplier = parseFloat(document.getElementById('batchMultiplier').value) || 1.0;\n        var grams = baseGrams * multiplier;\n\n        var rawIng = document.getElementById('ingredientSelect').value.split('|');\n        var baseCupWeight = parseFloat(rawIng[0]) || 120;\n        var ingName = rawIng[1];\n        var densityGmL = parseFloat(rawIng[2]) || (baseCupWeight / 236.588);\n\n        var rawStd = document.getElementById('cupStandardSelect').value.split('|');\n        var cupVolumeMl = parseFloat(rawStd[0]) || 236.588;\n        var stdName = rawStd[1];\n\n        var adjustedCupWeight = baseCupWeight * (cupVolumeMl / 236.588);\n\n        var decimalCups = grams > 0 ? (grams / adjustedCupWeight) : 0;\n        var tbsp = decimalCups * 16;\n        var tsp = decimalCups * 48;\n        var oz = grams / 28.34952;\n        var lb = grams / 453.59237;\n        var totalMl = grams / densityGmL;\n        var flOz = totalMl / 29.5735;\n\n        var fractionText = toChefCookingFraction(decimalCups);\n\n        document.getElementById('densityBadge').textContent = densityGmL.toFixed(3) + ' g/mL';\n\n        var container = document.getElementById('cupResults');\n        container.innerHTML = \n          '<div style=\"padding: 0.85rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n            '<span style=\"color: var(--text-muted); font-size: 0.75rem; text-transform: uppercase;\">Chef Practical Measure</span>' +\n            '<div style=\"font-size: 1.6rem; font-weight: bold; color: #10b981; margin: 0.2rem 0; font-family: var(--mono);\">' + fractionText + '</div>' +\n            '<div style=\"font-size: 0.78rem; color: var(--text-muted);\">' + (multiplier !== 1 ? 'Scaled for ' + multiplier + '× batch (' + grams.toFixed(1) + 'g)' : 'Easiest way to measure with standard cups & spoons') + '</div>' +\n          '</div>' +\n          '<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;\">' +\n            '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n              '<span style=\"color: var(--text-muted); font-size: 0.72rem; text-transform: uppercase;\">Decimal Cups</span>' +\n              '<div style=\"font-size: 1.25rem; font-weight: bold; color: var(--fg); font-family: var(--mono);\">' + decimalCups.toFixed(2) + ' Cups</div>' +\n              '<div style=\"font-size: 0.72rem; color: var(--text-muted);\">' + stdName.split(' ')[0] + ' (' + cupVolumeMl.toFixed(1) + ' mL)</div>' +\n            '</div>' +\n            '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n              '<span style=\"color: var(--text-muted); font-size: 0.72rem; text-transform: uppercase;\">Tablespoons & Tsp</span>' +\n              '<div style=\"font-size: 1.25rem; font-weight: bold; color: #3b82f6; font-family: var(--mono);\">' + tbsp.toFixed(1) + ' Tbsp</div>' +\n              '<div style=\"font-size: 0.72rem; color: var(--text-muted);\">' + tsp.toFixed(0) + ' Teaspoons (tsp)</div>' +\n            '</div>' +\n          '</div>' +\n          '<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;\">' +\n            '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n              '<span style=\"color: var(--text-muted); font-size: 0.72rem; text-transform: uppercase;\">Avoirdupois Ounces</span>' +\n              '<div style=\"font-size: 1.1rem; font-weight: bold; color: var(--fg); font-family: var(--mono);\">' + oz.toFixed(2) + ' oz</div>' +\n              '<div style=\"font-size: 0.72rem; color: var(--text-muted);\">' + (lb >= 0.1 ? lb.toFixed(3) + ' lbs' : grams.toFixed(1) + ' g') + '</div>' +\n            '</div>' +\n            '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n              '<span style=\"color: var(--text-muted); font-size: 0.72rem; text-transform: uppercase;\">Liquid Volume (mL / fl oz)</span>' +\n              '<div style=\"font-size: 1.1rem; font-weight: bold; color: var(--fg); font-family: var(--mono);\">' + totalMl.toFixed(1) + ' mL</div>' +\n              '<div style=\"font-size: 0.72rem; color: var(--text-muted);\">' + flOz.toFixed(2) + ' fl oz</div>' +\n            '</div>' +\n          '</div>';\n\n        var deriv = document.getElementById('derivationFormula');\n        deriv.innerHTML = \n          '<div><strong>1. Bulk Density of ' + ingName + ':</strong> &rho; = ' + densityGmL.toFixed(3) + ' g/mL (' + baseCupWeight + ' g per 236.6 mL US cup)</div>' +\n          '<div><strong>2. Cup Standard Selected:</strong> ' + stdName + ' = ' + cupVolumeMl.toFixed(1) + ' mL per cup</div>' +\n          '<div><strong>3. Calibrated Weight per Single Cup:</strong> W<sub>cup</sub> = ' + densityGmL.toFixed(3) + ' &times; ' + cupVolumeMl.toFixed(1) + ' mL = ' + adjustedCupWeight.toFixed(1) + ' g/cup</div>' +\n          '<div><strong>4. Volume in Cups:</strong> Cups = ' + grams.toFixed(1) + ' g / ' + adjustedCupWeight.toFixed(1) + ' g = <strong>' + decimalCups.toFixed(3) + ' cups</strong></div>' +\n          '<div><strong>5. Practical Equivalents:</strong> ' + decimalCups.toFixed(2) + ' cups &times; 16 = <strong>' + tbsp.toFixed(1) + ' Tbsp</strong> = <strong>' + tsp.toFixed(1) + ' tsp</strong> (' + fractionText + ')</div>';\n\n        currentConversionData = {\n          grams: grams.toFixed(1),\n          ingredient: ingName,\n          cupStandard: stdName,\n          decimalCups: decimalCups.toFixed(2),\n          fractionText: fractionText,\n          tbsp: tbsp.toFixed(1),\n          tsp: tsp.toFixed(0),\n          oz: oz.toFixed(2)\n        };\n\n        document.getElementById('cupFillBadge').textContent = decimalCups.toFixed(2) + ' Cups';\n        renderCupSvg(decimalCups, grams, oz);\n      }\n\n      function renderCupSvg(cupFraction, grams, oz) {\n        var container = document.getElementById('cupSvgContainer');\n        if (!container) return;\n\n        var clampedFraction = Math.min(Math.max(cupFraction, 0), 1.25);\n        var fillPct = Math.min(clampedFraction, 1.0);\n\n        var baseY = 175;\n        var topY = 55;\n        var cupH = baseY - topY;\n        var currentY = baseY - (fillPct * cupH);\n\n        var t = (baseY - currentY) / (baseY - topY);\n        var halfW = (65 + t * 25);\n        var leftX = 150 - halfW;\n        var rightX = 150 + halfW;\n\n        var baseLeftX = 85;\n        var baseRightX = 215;\n\n        var fillPath = '';\n        if (fillPct > 0.01) {\n          fillPath = \n            '<path d=\"M ' + baseLeftX + ' ' + baseY + ' L ' + leftX + ' ' + currentY + ' Q 150 ' + (currentY + 4) + ' ' + rightX + ' ' + currentY + ' L ' + baseRightX + ' ' + baseY + ' Q 150 ' + (baseY + 4) + ' ' + baseLeftX + ' ' + baseY + ' Z\" fill=\"rgba(59, 130, 246, 0.22)\" stroke=\"#3b82f6\" stroke-width=\"1.5\" />' +\n            '<line x1=\"' + leftX + '\" y1=\"' + currentY + '\" x2=\"' + rightX + '\" y2=\"' + currentY + '\" stroke=\"#3b82f6\" stroke-width=\"2\" />';\n        }\n\n        var svg = \n          '<svg viewBox=\"0 0 420 200\" style=\"width: 100%; max-width: 480px; height: auto; display: block; font-family: var(--mono); margin: 0 auto;\" xmlns=\"http://www.w3.org/2000/svg\">' +\n            '<path d=\"M 235 70 C 280 70, 285 155, 215 160\" fill=\"none\" stroke=\"var(--border-strong)\" stroke-width=\"8\" stroke-linecap=\"round\" />' +\n            '<path d=\"M 45 35 L 60 40 L 85 175 Q 150 183 215 175 L 240 40 L 245 35 Q 150 42 45 35 Z\" fill=\"rgba(100, 116, 139, 0.05)\" stroke=\"var(--border-strong)\" stroke-width=\"2.5\" />' +\n            fillPath +\n            '<line x1=\"190\" y1=\"55\" x2=\"235\" y2=\"55\" stroke=\"var(--fg)\" stroke-width=\"2\" />' +\n            '<text x=\"250\" y=\"59\" fill=\"var(--fg)\" font-size=\"11\" font-weight=\"bold\">1 Cup</text>' +\n            '<line x1=\"195\" y1=\"85\" x2=\"230\" y2=\"85\" stroke=\"var(--text-muted)\" stroke-width=\"1.5\" />' +\n            '<text x=\"250\" y=\"89\" fill=\"var(--text-muted)\" font-size=\"10\">3/4 Cup</text>' +\n            '<line x1=\"197\" y1=\"95\" x2=\"228\" y2=\"95\" stroke=\"var(--border-strong)\" stroke-dasharray=\"2,2\" stroke-width=\"1\" />' +\n            '<text x=\"250\" y=\"99\" fill=\"var(--text-muted)\" font-size=\"9\">2/3 Cup</text>' +\n            '<line x1=\"200\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--text-muted)\" stroke-width=\"1.5\" />' +\n            '<text x=\"250\" y=\"119\" fill=\"var(--text-muted)\" font-size=\"10\">1/2 Cup</text>' +\n            '<line x1=\"202\" y1=\"135\" x2=\"222\" y2=\"135\" stroke=\"var(--border-strong)\" stroke-dasharray=\"2,2\" stroke-width=\"1\" />' +\n            '<text x=\"250\" y=\"139\" fill=\"var(--text-muted)\" font-size=\"9\">1/3 Cup</text>' +\n            '<line x1=\"204\" y1=\"145\" x2=\"220\" y2=\"145\" stroke=\"var(--text-muted)\" stroke-width=\"1.5\" />' +\n            '<text x=\"250\" y=\"149\" fill=\"var(--text-muted)\" font-size=\"10\">1/4 Cup</text>' +\n            '<rect x=\"295\" y=\"110\" width=\"115\" height=\"55\" rx=\"5\" fill=\"var(--surface-alt)\" stroke=\"var(--border)\" stroke-width=\"1\" />' +\n            '<text x=\"352\" y=\"128\" fill=\"var(--text-muted)\" font-size=\"9\" text-anchor=\"middle\" text-transform=\"uppercase\">Scale Readout</text>' +\n            '<text x=\"352\" y=\"146\" fill=\"#10b981\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\">' + grams.toFixed(1) + ' g</text>' +\n            '<text x=\"352\" y=\"159\" fill=\"var(--text-muted)\" font-size=\"9\" text-anchor=\"middle\">' + oz.toFixed(2) + ' oz</text>' +\n          '</svg>';\n\n        container.innerHTML = svg;\n      }\n\n      function toChefCookingFraction(val) {\n        if (val <= 0) return '0 Cups';\n        var whole = Math.floor(val);\n        var rem = val - whole;\n\n        var fracStr = '';\n        if (rem < 0.06) {\n          fracStr = '';\n        } else if (rem >= 0.06 && rem < 0.18) {\n          fracStr = '1/8 Cup';\n        } else if (rem >= 0.18 && rem < 0.29) {\n          fracStr = '1/4 Cup';\n        } else if (rem >= 0.29 && rem < 0.41) {\n          fracStr = '1/3 Cup';\n        } else if (rem >= 0.41 && rem < 0.58) {\n          fracStr = '1/2 Cup';\n        } else if (rem >= 0.58 && rem < 0.70) {\n          fracStr = '2/3 Cup';\n        } else if (rem >= 0.70 && rem < 0.85) {\n          fracStr = '3/4 Cup';\n        } else if (rem >= 0.85 && rem < 0.94) {\n          fracStr = '7/8 Cup';\n        } else {\n          whole += 1;\n          fracStr = '';\n        }\n\n        var parts = [];\n        if (whole > 0) {\n          parts.push(whole + (fracStr ? ' ' + fracStr : ' Cup' + (whole > 1 ? 's' : '')));\n        } else if (fracStr) {\n          parts.push(fracStr);\n        }\n\n        var totalTbsp = val * 16;\n        var tbspRemainder = totalTbsp % 16;\n        var wholeTbsp = Math.floor(tbspRemainder);\n        var tspRemainder = Math.round((tbspRemainder - wholeTbsp) * 3);\n\n        if (parts.length === 0) {\n          if (wholeTbsp > 0) parts.push(wholeTbsp + ' Tbsp');\n          if (tspRemainder > 0) parts.push(tspRemainder + ' tsp');\n        }\n\n        return parts.length > 0 ? parts.join(' + ') : '0 Cups';\n      }\n\n      function copyBakingTakeoff() {\n        if (!currentConversionData) return;\n        var text = \n          'RECIPE MEASUREMENT CONVERSION\\n' +\n          '• Ingredient: ' + currentConversionData.ingredient + '\\n' +\n          '• Practical Measure: ' + currentConversionData.fractionText + '\\n' +\n          '• Decimal Volume: ' + currentConversionData.decimalCups + ' Cups\\n' +\n          '• Spoons: ' + currentConversionData.tbsp + ' Tablespoons (' + currentConversionData.tsp + ' tsp)\\n' +\n          '• Weight: ' + currentConversionData.oz + ' oz (' + currentConversionData.grams + ' grams)\\n' +\n          '• Standard: ' + currentConversionData.cupStandard + '\\n' +\n          '----------------------------------------\\n' +\n          'Calculated via Digital Tools Shed: https://digitaltoolsshed.com/calc/grams-to-cups';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyBakingBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '✓ Copied Recipe Line to Clipboard!';\n          btn.style.background = '#10b981';\n          btn.style.color = '#fff';\n          setTimeout(function() {\n            btn.innerHTML = orig;\n            btn.style.background = 'var(--surface-alt)';\n            btn.style.color = 'var(--fg)';\n          }, 2200);\n        });\n      }\n\n      document.addEventListener('DOMContentLoaded', calcGramsToCups);\n      calcGramsToCups();\n    </script>\n  ";

  writeFileSync(join(calcDir, 'grams-to-cups.html'), renderKitchenPage({
    title: 'Grams to Cups Converter (By Ingredient & Cup Size) | Digital Tools Shed',
    metaDesc: 'Convert grams to cups by ingredient with USDA density factors. Supports flour, sugar, butter, oil, oats, and kosher salt across US Customary, Metric, and Imperial cups.',
    canonical: `${DOMAIN}/calc/grams-to-cups`,
    bodyContent: gramsToCupsBody,
    currentPath: '/calc/grams-to-cups',
    faq: [
      { q: 'How many cups is 100 grams of flour?', a: '100 grams of all-purpose flour (spooned and leveled) is equal to approximately 0.83 US cups (roughly 3/4 cup + 1 tablespoon + 1 teaspoon).' },
      { q: 'Why is 1 cup of flour not equal to 1 cup of sugar?', a: 'Cups measure volume, while grams measure mass. Granulated sugar consists of dense crystalline sucrose (200g per cup), whereas flour is aerated grain starch (120g per cup). Always convert culinary ingredients by physical bulk density.' },
      { q: 'What is the difference between a US cup and a Metric cup?', a: 'A US Customary cup holds 236.6 mL (8 fluid ounces), a US Legal nutrition cup holds 240.0 mL, while a Metric cup (used in Australia, New Zealand, Canada, and the UK) holds 250.0 mL. Recipes from Australia or Britain require 5.7% more volume than US recipes.' },
      { q: 'What is the difference between Diamond Crystal and Morton kosher salt?', a: 'Diamond Crystal kosher salt has hollow flaky crystals weighing 144g per cup (2.8g per tsp), whereas Morton kosher salt consists of dense rolled flakes weighing 240g per cup (4.8g per tsp). Substituting Morton 1:1 by volume for Diamond Crystal causes 67% over-salting.' },
      { q: 'How do you convert grams to tablespoons and teaspoons without measuring cups?', a: 'One level tablespoon equals 1/16 of a cup (roughly 14.8 mL), and one teaspoon equals 1/3 of a tablespoon (4.93 mL). For flour (120g/cup), 1 tablespoon equals 7.5 grams, and 1 teaspoon equals 2.5 grams. For granulated sugar (200g/cup), 1 tablespoon equals 12.5 grams, and 1 teaspoon equals 4.17 grams.' }
    ]
  }));

  const cupsToGramsBody = "\n    <div class=\"article-container\" style=\"max-width: 950px;\">\n      <nav style=\"font-family: var(--mono); font-size: 0.8rem; margin-bottom: 1.5rem; color: var(--text-muted);\">\n        <a href=\"/\">Home</a> &gt; <a href=\"/calc/\">Calculators</a> &gt; Cups to Grams\n      </nav>\n\n      <header style=\"margin-bottom: 2rem;\">\n        <h1 style=\"font-family: var(--serif); font-size: 2.2rem; margin-bottom: 0.5rem;\">Cups to Grams Converter (By Ingredient & Standard)</h1>\n        <p style=\"color: var(--text-muted); font-size: 1.05rem; line-height: 1.6;\">\n          Convert US cups, recipe fractions, and spoons to precision digital scale grams (g), ounces (oz), and pounds (lb) using calibrated USDA culinary bulk densities and live measuring cup gauge.\n        </p>\n      </header>\n\n      <!-- Key Callout -->\n      <div style=\"background: var(--surface-alt); border-left: 4px solid var(--border-strong); padding: 0.85rem 1.15rem; margin-bottom: 1.5rem; font-size: 0.95rem; font-family: var(--serif);\">\n        <strong>Digital Scales Guarantee Bakery Consistency:</strong> Measuring by volume with cups introduces up to <strong>&plusmn;25% variance</strong> depending on humidity, packing technique, and scoop compaction. Converting cups to grams ensures every loaf, cookie, and pastry rises identically every single time.\n      </div>\n\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1.5rem; margin-bottom: 2rem;\">\n        <!-- Input Card -->\n        <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px;\">\n          <h3 style=\"font-family: var(--serif); font-size: 1.2rem; margin-bottom: 1.25rem; color: var(--fg);\">Ingredient & Cup Volume</h3>\n\n          <div style=\"margin-bottom: 1.25rem;\">\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Select Ingredient</label>\n            <select id=\"ingredientSelectCups\" onchange=\"calcCupsToGrams()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--sans); border-radius: 4px; font-size: 0.95rem;\">\n              \n              <optgroup label=\"Flours & Powders\">\n                <option value=\"120|All-Purpose Flour (Spooned & Leveled)|0.507\" selected>All-Purpose Flour (Spooned & Leveled) - 120g</option>\n                <option value=\"145|All-Purpose Flour (Dipped / Packed)|0.613\">All-Purpose Flour (Dipped / Packed) - 145g</option>\n                <option value=\"127|Bread Flour|0.537\">Bread Flour - 127g</option>\n                <option value=\"130|Whole Wheat Flour|0.549\">Whole Wheat Flour - 130g</option>\n                <option value=\"114|Cake Flour (Sifted)|0.482\">Cake Flour (Sifted) - 114g</option>\n                <option value=\"96|Almond Flour (Blanched)|0.406\">Almond Flour (Blanched) - 96g</option>\n                <option value=\"112|Coconut Flour|0.473\">Coconut Flour - 112g</option>\n                <option value=\"128|Cornstarch|0.541\">Cornstarch - 128g</option>\n                <option value=\"85|Cocoa Powder (Unsweetened)|0.359\">Cocoa Powder (Unsweetened) - 85g</option>\n                <option value=\"192|Baking Powder|0.812\">Baking Powder - 192g</option>\n                <option value=\"220|Baking Soda|0.930\">Baking Soda - 220g</option>\n              </optgroup>\n              <optgroup label=\"Sugars & Sweeteners\">\n                <option value=\"200|Granulated White Sugar|0.845\">Granulated White Sugar - 200g</option>\n                <option value=\"220|Brown Sugar (Firmly Packed)|0.930\">Brown Sugar (Firmly Packed) - 220g</option>\n                <option value=\"145|Brown Sugar (Loose / Unpacked)|0.613\">Brown Sugar (Loose / Unpacked) - 145g</option>\n                <option value=\"100|Powdered / Icing Sugar (Sifted)|0.423\">Powdered / Icing Sugar (Sifted) - 100g</option>\n                <option value=\"125|Powdered Sugar (Unsifted)|0.528\">Powdered Sugar (Unsifted) - 125g</option>\n                <option value=\"340|Honey / Molasses|1.437\">Honey / Molasses - 340g</option>\n                <option value=\"312|Pure Maple Syrup|1.319\">Pure Maple Syrup - 312g</option>\n              </optgroup>\n              <optgroup label=\"Dairy, Fats & Liquids\">\n                <option value=\"227|Butter (Unsalted/Salted - 2 Sticks)|0.959\">Butter (2 Sticks = 1 Cup) - 227g</option>\n                <option value=\"218|Vegetable / Canola Oil|0.921\">Vegetable / Canola Oil - 218g</option>\n                <option value=\"216|Olive Oil|0.913\">Olive Oil - 216g</option>\n                <option value=\"244|Whole Milk|1.031\">Whole Milk - 244g</option>\n                <option value=\"238|Heavy Whipping Cream|1.006\">Heavy Whipping Cream - 238g</option>\n                <option value=\"240|Sour Cream / Greek Yogurt|1.014\">Sour Cream / Greek Yogurt - 240g</option>\n                <option value=\"270|Peanut Butter (Smooth)|1.141\">Peanut Butter (Smooth) - 270g</option>\n                <option value=\"237|Water (Pure)|1.000\">Water - 237g (236.6 mL)</option>\n              </optgroup>\n              <optgroup label=\"Grains, Seeds & Dry Goods\">\n                <option value=\"90|Rolled Oats (Old Fashioned)|0.380\">Rolled Oats (Old Fashioned) - 90g</option>\n                <option value=\"80|Quick Oats|0.338\">Quick Oats - 80g</option>\n                <option value=\"160|Steel Cut Oats|0.676\">Steel Cut Oats - 160g</option>\n                <option value=\"185|White Rice (Uncooked Long-Grain)|0.782\">White Rice (Uncooked) - 185g</option>\n                <option value=\"190|Brown Rice (Uncooked)|0.803\">Brown Rice (Uncooked) - 190g</option>\n                <option value=\"170|Quinoa (Uncooked)|0.719\">Quinoa (Uncooked) - 170g</option>\n                <option value=\"112|Breadcrumbs (Dry)|0.473\">Breadcrumbs (Dry) - 112g</option>\n              </optgroup>\n              <optgroup label=\"Salts\">\n                <option value=\"288|Table Salt (Fine)|1.217\">Table Salt (Fine) - 288g</option>\n                <option value=\"240|Morton Kosher Salt|1.014\">Morton Kosher Salt - 240g</option>\n                <option value=\"144|Diamond Crystal Kosher Salt|0.609\">Diamond Crystal Kosher Salt - 144g</option>\n              </optgroup>\n              <optgroup label=\"Mix-ins & Nuts\">\n                <option value=\"170|Chocolate Chips (Semi-Sweet)|0.719\">Chocolate Chips (Semi-Sweet) - 170g</option>\n                <option value=\"115|Walnuts / Pecans (Chopped)|0.486\">Walnuts / Pecans (Chopped) - 115g</option>\n                <option value=\"150|Raisins (Seedless)|0.634\">Raisins (Seedless) - 150g</option>\n              </optgroup>\n  \n            </select>\n          </div>\n\n          <div style=\"margin-bottom: 1.25rem;\">\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Number of Cups</label>\n            <input type=\"number\" id=\"cupsInput\" value=\"1.0\" min=\"0.01\" step=\"any\" oninput=\"calcCupsToGrams()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--mono); font-size: 1.15rem; border-radius: 4px;\">\n            <div style=\"display: flex; gap: 0.35rem; margin-top: 0.5rem; flex-wrap: wrap;\">\n              <button type=\"button\" onclick=\"setCupFraction(0.125)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">1/8</button>\n              <button type=\"button\" onclick=\"setCupFraction(0.25)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">1/4</button>\n              <button type=\"button\" onclick=\"setCupFraction(0.333)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">1/3</button>\n              <button type=\"button\" onclick=\"setCupFraction(0.5)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">1/2</button>\n              <button type=\"button\" onclick=\"setCupFraction(0.667)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">2/3</button>\n              <button type=\"button\" onclick=\"setCupFraction(0.75)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">3/4</button>\n              <button type=\"button\" onclick=\"setCupFraction(1.0)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">1 Cup</button>\n              <button type=\"button\" onclick=\"setCupFraction(1.5)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">1.5</button>\n              <button type=\"button\" onclick=\"setCupFraction(2.0)\" class=\"btn-subtle\" style=\"font-size: 0.75rem; padding: 0.2rem 0.5rem; font-family: var(--mono); background: var(--surface-alt); border: 1px solid var(--border); border-radius: 3px; cursor: pointer;\">2 Cups</button>\n            </div>\n          </div>\n\n          <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; margin-bottom: 1.25rem;\">\n            <div>\n              <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Cup Standard</label>\n              <select id=\"cupStandardSelectCups\" onchange=\"calcCupsToGrams()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--sans); border-radius: 4px; font-size: 0.85rem;\">\n                <option value=\"236.588|US Customary (236.6 mL)\" selected>US Customary (236.6 mL)</option>\n                <option value=\"240.000|US Legal / Nutrition (240.0 mL)\">US Legal (240.0 mL)</option>\n                <option value=\"250.000|Metric Cup (250.0 mL - UK/AU/NZ)\">Metric Cup (250.0 mL)</option>\n                <option value=\"284.130|Imperial Cup (284.1 mL - Traditional UK)\">Imperial Cup (284.1 mL)</option>\n              </select>\n            </div>\n\n            <div>\n              <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Batch Multiplier</label>\n              <select id=\"batchMultiplierCups\" onchange=\"calcCupsToGrams()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); font-family: var(--sans); border-radius: 4px; font-size: 0.85rem;\">\n                <option value=\"0.5\">0.5× (Half Batch)</option>\n                <option value=\"1\" selected>1× (Standard Recipe)</option>\n                <option value=\"1.5\">1.5× (1.5× Recipe)</option>\n                <option value=\"2\">2× (Double Batch)</option>\n                <option value=\"3\">3× (Triple Batch)</option>\n              </select>\n            </div>\n          </div>\n\n          <div style=\"font-family: var(--mono); font-size: 0.78rem; color: var(--text-muted); padding: 0.5rem; background: var(--surface-alt); border-radius: 4px; display: flex; justify-content: space-between;\">\n            <span>Ingredient Density:</span>\n            <span id=\"densityBadgeCups\" style=\"font-weight: bold; color: var(--fg);\">-- g/mL</span>\n          </div>\n        </div>\n\n        <!-- Output & Visual Card -->\n        <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; display: flex; flex-direction: column; justify-content: space-between;\">\n          <div>\n            <h3 style=\"font-family: var(--serif); font-size: 1.2rem; margin-bottom: 1rem; color: var(--fg);\">Precision Scale Weight</h3>\n            <div id=\"cupsResultsContainer\" style=\"display: flex; flex-direction: column; gap: 0.75rem;\">\n              <!-- Populated by JS -->\n            </div>\n          </div>\n\n          <!-- Pure SVG Measuring Cup Visualizer -->\n          <div style=\"margin-top: 1.25rem; padding-top: 1rem; border-top: 1px solid var(--border);\">\n            <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem;\">\n              <span style=\"font-family: var(--mono); font-size: 0.75rem; text-transform: uppercase; color: var(--text-muted);\">Measuring Cup Fill Gauge</span>\n              <span id=\"cupFillBadgeCups\" style=\"font-family: var(--mono); font-size: 0.75rem; color: #10b981; font-weight: bold;\">1.00 Cup</span>\n            </div>\n            <div id=\"cupSvgContainerCups\">\n              <!-- SVG drawn by JS -->\n            </div>\n          </div>\n\n          <div style=\"margin-top: 1rem;\">\n            <button type=\"button\" id=\"copyCupsBtn\" onclick=\"copyCupsTakeoff()\" class=\"btn\" style=\"width: 100%; padding: 0.65rem; font-family: var(--mono); font-size: 0.85rem; font-weight: bold; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); border-radius: 4px; cursor: pointer; transition: all 0.2s;\">\n              📋 Copy Scale Measurement Line\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Step-by-Step Mathematical & Physical Derivation -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin: 0 0 0.75rem; color: var(--fg);\">📐 Bulk Density & Tare Mass Derivation</h3>\n        <p style=\"font-size: 0.95rem; line-height: 1.6; color: var(--text-muted); margin-bottom: 1rem;\">\n          How the physical bulk density converts recipe volume fractions into grams and ounces:\n        </p>\n        <div id=\"derivationFormulaCups\" style=\"font-family: var(--mono); font-size: 0.85rem; line-height: 1.8; background: var(--surface-alt); padding: 1rem; border-radius: 4px; border: 1px solid var(--border);\">\n          <!-- Injected dynamically -->\n        </div>\n      </div>\n\n      <!-- 5 Fatal Pitfalls Section -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin-top: 0; margin-bottom: 0.75rem; color: var(--fg);\">⚠️ 5 Fatal Baking Pitfalls & Volumetric Measurement Traps</h3>\n        <p style=\"color: var(--text-muted); font-size: 0.95rem; line-height: 1.6; margin-bottom: 1.25rem;\">\n          Baking is strict chemical engineering. In chemistry, small volumetric deviations spoil pH, gluten hydration, and steam leavening. Avoid these 5 traps:\n        </p>\n\n        <div style=\"display: grid; gap: 1rem;\">\n          <div class=\"trap-card\" style=\"border-left: 4px solid #ef4444;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">1. The Scoop vs Spoon-and-Sweep Flour Compaction Shock</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Dipping a measuring cup directly into a bag of flour compacts the grain. A cup dipped and leveled weighs <strong>140g to 155g</strong>, whereas properly aerated flour (spooned into the cup and leveled) weighs <strong>120g</strong>. That extra 25g to 35g of flour per cup absorbs excessive liquid, turning tender cakes rubbery and artisan breads dense and dry.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #f59e0b;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">2. The Diamond Crystal vs Morton Kosher Salt Discrepancy</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Diamond Crystal kosher salt has hollow flaky crystals weighing only <strong>144g per cup</strong> (2.8g per tsp), whereas Morton kosher salt is dense rolled crystals weighing <strong>240g per cup</strong> (4.8g per tsp). Substituting Morton 1:1 by volume for Diamond Crystal makes your food nearly <strong>70% saltier</strong> than intended.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #10b981;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">3. The International Cup Volume Chasm (US vs Metric vs Imperial)</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              A US Customary cup holds <strong>236.6 mL</strong> (8 fluid ounces), a US Legal nutrition cup holds <strong>240.0 mL</strong>, an Australian / New Zealand / UK Metric cup holds <strong>250.0 mL</strong>, and an archaic Imperial British cup holds <strong>284.1 mL</strong>. Baking a British or Australian recipe using an American cup creates a 5.7% to 20% shortage of flour and sugar.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #3b82f6;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">4. The Brown Sugar Entrapped Air Trap (Packed vs Loose)</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Brown sugar contains sticky molasses that traps massive air pockets when scooped loosely, yielding only ~145g per cup. Standard baking recipes universally assume <strong>firmly packed brown sugar</strong> (pressed into the cup until it holds its shape like a sandcastle), which weighs <strong>220g per cup</strong>. Scooping loosely causes a disastrous 34% sugar deficit.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #8b5cf6;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">5. Fluid Ounces (Volume) vs Avoirdupois Ounces (Weight) Confusion</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              A \"fluid ounce\" is a unit of volume ($29.57\\text{ mL}$), while an ounce is a unit of mass ($28.35\\text{ g}$). Water is the only culinary substance where $1\\text{ fl oz} \\approx 1\\text{ oz}$ mass. For dense honey, an 8 fl oz cup weighs over <strong>11.5 dry ounces (340 grams)</strong>. Weighing honey to \"8 ounces\" on a scale results in a 30% shortage.\n            </p>\n          </div>\n        </div>\n      </div>\n\n      <!-- Master Reference Table -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin-top: 0; margin-bottom: 1rem; color: var(--fg);\">📋 Master Baking Conversion Table (US Customary Cups to Grams)</h3>\n        <div style=\"overflow-x: auto;\">\n          <table style=\"width: 100%; border-collapse: collapse; font-family: var(--sans); font-size: 0.85rem; text-align: left;\">\n            <thead>\n              <tr style=\"background: var(--surface-alt); border-bottom: 2px solid var(--border);\">\n                <th style=\"padding: 0.55rem 0.75rem;\">Ingredient</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">1/4 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">1/3 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">1/2 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem;\">3/4 Cup</th>\n                <th style=\"padding: 0.55rem 0.75rem; color: #10b981;\">1 Cup</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">All-Purpose Flour (Spooned & Leveled)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">30g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">40g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">60g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">90g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">120g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Bread Flour</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">31.8g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">42.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">63.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">95.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">127g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Granulated White Sugar</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">50g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">66.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">100g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">150g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">200g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Brown Sugar (Packed)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">55g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">73.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">110g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">165g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">220g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Powdered Sugar (Sifted)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">25g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">33.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">50g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">75g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">100g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Butter (1 stick = 1/2 cup)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">56.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">75.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">113.4g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">170.1g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">227g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Vegetable / Canola Oil</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">54.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">72.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">109g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">163.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">218g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Rolled Oats</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">22.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">30g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">45g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">67.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">90g</td></tr>\n              <tr style=\"border-bottom: 1px solid var(--border);\"><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Cocoa Powder (Unsweetened)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">21.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">28.3g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">42.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">63.8g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">85g</td></tr>\n              <tr><td style=\"padding: 0.45rem 0.75rem; font-weight: bold;\">Chocolate Chips (Semi-Sweet)</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">42.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">56.7g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">85g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono);\">127.5g</td><td style=\"padding: 0.45rem 0.75rem; font-family: var(--mono); font-weight: bold; color: #10b981;\">170g</td></tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n\n    <script>\n      var currentCupsData = null;\n\n      function setCupFraction(val) {\n        document.getElementById('cupsInput').value = val;\n        calcCupsToGrams();\n      }\n\n      function calcCupsToGrams() {\n        var baseCups = parseFloat(document.getElementById('cupsInput').value) || 0;\n        var multiplier = parseFloat(document.getElementById('batchMultiplierCups').value) || 1.0;\n        var cups = baseCups * multiplier;\n\n        var rawIng = document.getElementById('ingredientSelectCups').value.split('|');\n        var baseCupWeight = parseFloat(rawIng[0]) || 120;\n        var ingName = rawIng[1];\n        var densityGmL = parseFloat(rawIng[2]) || (baseCupWeight / 236.588);\n\n        var rawStd = document.getElementById('cupStandardSelectCups').value.split('|');\n        var cupVolumeMl = parseFloat(rawStd[0]) || 236.588;\n        var stdName = rawStd[1];\n\n        var adjustedCupWeight = baseCupWeight * (cupVolumeMl / 236.588);\n\n        var grams = cups * adjustedCupWeight;\n        var kg = grams / 1000;\n        var oz = grams / 28.34952;\n        var lb = grams / 453.59237;\n        var tbsp = cups * 16;\n        var tsp = cups * 48;\n        var ml = cups * cupVolumeMl;\n\n        document.getElementById('densityBadgeCups').textContent = densityGmL.toFixed(3) + ' g/mL';\n\n        var container = document.getElementById('cupsResultsContainer');\n        container.innerHTML = \n          '<div style=\"padding: 0.85rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n            '<span style=\"color: var(--text-muted); font-size: 0.75rem; text-transform: uppercase;\">Digital Scale Mass</span>' +\n            '<div style=\"font-size: 1.8rem; font-weight: bold; color: #10b981; margin: 0.2rem 0; font-family: var(--mono);\">' + grams.toFixed(1) + ' grams</div>' +\n            '<div style=\"font-size: 0.78rem; color: var(--text-muted);\">' + (multiplier !== 1 ? 'Scaled for ' + multiplier + '× batch (' + cups.toFixed(2) + ' cups total)' : 'Exact tare mass for digital scales') + '</div>' +\n          '</div>' +\n          '<div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;\">' +\n            '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n              '<span style=\"color: var(--text-muted); font-size: 0.72rem; text-transform: uppercase;\">Avoirdupois Ounces</span>' +\n              '<div style=\"font-size: 1.25rem; font-weight: bold; color: var(--fg); font-family: var(--mono);\">' + oz.toFixed(2) + ' oz</div>' +\n              '<div style=\"font-size: 0.72rem; color: var(--text-muted);\">' + (lb >= 0.1 ? lb.toFixed(3) + ' lbs' : kg.toFixed(3) + ' kg') + '</div>' +\n            '</div>' +\n            '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 4px;\">' +\n              '<span style=\"color: var(--text-muted); font-size: 0.72rem; text-transform: uppercase;\">Spoons Equivalent</span>' +\n              '<div style=\"font-size: 1.25rem; font-weight: bold; color: #3b82f6; font-family: var(--mono);\">' + tbsp.toFixed(1) + ' Tbsp</div>' +\n              '<div style=\"font-size: 0.72rem; color: var(--text-muted);\">' + tsp.toFixed(0) + ' tsp (' + ml.toFixed(1) + ' mL)</div>' +\n            '</div>' +\n          '</div>';\n\n        var deriv = document.getElementById('derivationFormulaCups');\n        deriv.innerHTML = \n          '<div><strong>1. Calibrated Density:</strong> &rho; = ' + densityGmL.toFixed(3) + ' g/mL (' + baseCupWeight + ' g per 236.6 mL US cup)</div>' +\n          '<div><strong>2. Cup Volume Standard:</strong> ' + stdName + ' = ' + cupVolumeMl.toFixed(1) + ' mL</div>' +\n          '<div><strong>3. Adjusted Single Cup Weight:</strong> W<sub>cup</sub> = ' + densityGmL.toFixed(3) + ' &times; ' + cupVolumeMl.toFixed(1) + ' mL = ' + adjustedCupWeight.toFixed(1) + ' g/cup</div>' +\n          '<div><strong>4. Scale Mass Calculation:</strong> Mass = ' + cups.toFixed(2) + ' cups &times; ' + adjustedCupWeight.toFixed(1) + ' g = <strong>' + grams.toFixed(1) + ' grams</strong> (' + oz.toFixed(2) + ' oz)</div>';\n\n        currentCupsData = {\n          cups: cups.toFixed(2),\n          ingredient: ingName,\n          grams: grams.toFixed(1),\n          oz: oz.toFixed(2),\n          tbsp: tbsp.toFixed(1),\n          stdName: stdName\n        };\n\n        document.getElementById('cupFillBadgeCups').textContent = cups.toFixed(2) + ' Cups';\n        renderCupSvgCups(cups, grams, oz);\n      }\n\n      function renderCupSvgCups(cupFraction, grams, oz) {\n        var container = document.getElementById('cupSvgContainerCups');\n        if (!container) return;\n\n        var clampedFraction = Math.min(Math.max(cupFraction, 0), 1.25);\n        var fillPct = Math.min(clampedFraction, 1.0);\n\n        var baseY = 175;\n        var topY = 55;\n        var cupH = baseY - topY;\n        var currentY = baseY - (fillPct * cupH);\n\n        var t = (baseY - currentY) / (baseY - topY);\n        var halfW = (65 + t * 25);\n        var leftX = 150 - halfW;\n        var rightX = 150 + halfW;\n\n        var baseLeftX = 85;\n        var baseRightX = 215;\n\n        var fillPath = '';\n        if (fillPct > 0.01) {\n          fillPath = \n            '<path d=\"M ' + baseLeftX + ' ' + baseY + ' L ' + leftX + ' ' + currentY + ' Q 150 ' + (currentY + 4) + ' ' + rightX + ' ' + currentY + ' L ' + baseRightX + ' ' + baseY + ' Q 150 ' + (baseY + 4) + ' ' + baseLeftX + ' ' + baseY + ' Z\" fill=\"rgba(16, 185, 129, 0.22)\" stroke=\"#10b981\" stroke-width=\"1.5\" />' +\n            '<line x1=\"' + leftX + '\" y1=\"' + currentY + '\" x2=\"' + rightX + '\" y2=\"' + currentY + '\" stroke=\"#10b981\" stroke-width=\"2\" />';\n        }\n\n        var svg = \n          '<svg viewBox=\"0 0 420 200\" style=\"width: 100%; max-width: 480px; height: auto; display: block; font-family: var(--mono); margin: 0 auto;\" xmlns=\"http://www.w3.org/2000/svg\">' +\n            '<path d=\"M 235 70 C 280 70, 285 155, 215 160\" fill=\"none\" stroke=\"var(--border-strong)\" stroke-width=\"8\" stroke-linecap=\"round\" />' +\n            '<path d=\"M 45 35 L 60 40 L 85 175 Q 150 183 215 175 L 240 40 L 245 35 Q 150 42 45 35 Z\" fill=\"rgba(100, 116, 139, 0.05)\" stroke=\"var(--border-strong)\" stroke-width=\"2.5\" />' +\n            fillPath +\n            '<line x1=\"190\" y1=\"55\" x2=\"235\" y2=\"55\" stroke=\"var(--fg)\" stroke-width=\"2\" />' +\n            '<text x=\"250\" y=\"59\" fill=\"var(--fg)\" font-size=\"11\" font-weight=\"bold\">1 Cup</text>' +\n            '<line x1=\"195\" y1=\"85\" x2=\"230\" y2=\"85\" stroke=\"var(--text-muted)\" stroke-width=\"1.5\" />' +\n            '<text x=\"250\" y=\"89\" fill=\"var(--text-muted)\" font-size=\"10\">3/4 Cup</text>' +\n            '<line x1=\"197\" y1=\"95\" x2=\"228\" y2=\"95\" stroke=\"var(--border-strong)\" stroke-dasharray=\"2,2\" stroke-width=\"1\" />' +\n            '<text x=\"250\" y=\"99\" fill=\"var(--text-muted)\" font-size=\"9\">2/3 Cup</text>' +\n            '<line x1=\"200\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--text-muted)\" stroke-width=\"1.5\" />' +\n            '<text x=\"250\" y=\"119\" fill=\"var(--text-muted)\" font-size=\"10\">1/2 Cup</text>' +\n            '<line x1=\"202\" y1=\"135\" x2=\"222\" y2=\"135\" stroke=\"var(--border-strong)\" stroke-dasharray=\"2,2\" stroke-width=\"1\" />' +\n            '<text x=\"250\" y=\"139\" fill=\"var(--text-muted)\" font-size=\"9\">1/3 Cup</text>' +\n            '<line x1=\"204\" y1=\"145\" x2=\"220\" y2=\"145\" stroke=\"var(--text-muted)\" stroke-width=\"1.5\" />' +\n            '<text x=\"250\" y=\"149\" fill=\"var(--text-muted)\" font-size=\"10\">1/4 Cup</text>' +\n            '<rect x=\"295\" y=\"110\" width=\"115\" height=\"55\" rx=\"5\" fill=\"var(--surface-alt)\" stroke=\"var(--border)\" stroke-width=\"1\" />' +\n            '<text x=\"352\" y=\"128\" fill=\"var(--text-muted)\" font-size=\"9\" text-anchor=\"middle\" text-transform=\"uppercase\">Scale Readout</text>' +\n            '<text x=\"352\" y=\"146\" fill=\"#10b981\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\">' + grams.toFixed(1) + ' g</text>' +\n            '<text x=\"352\" y=\"159\" fill=\"var(--text-muted)\" font-size=\"9\" text-anchor=\"middle\">' + oz.toFixed(2) + ' oz</text>' +\n          '</svg>';\n\n        container.innerHTML = svg;\n      }\n\n      function copyCupsTakeoff() {\n        if (!currentCupsData) return;\n        var text = \n          'RECIPE MEASUREMENT CONVERSION\\n' +\n          '• Ingredient: ' + currentCupsData.ingredient + '\\n' +\n          '• Volume: ' + currentCupsData.cups + ' Cups\\n' +\n          '• Scale Weight: ' + currentCupsData.grams + ' g (' + currentCupsData.oz + ' oz)\\n' +\n          '• Equivalent Spoons: ' + currentCupsData.tbsp + ' Tablespoons\\n' +\n          '• Cup Size Standard: ' + currentCupsData.stdName + '\\n' +\n          '----------------------------------------\\n' +\n          'Calculated via Digital Tools Shed: https://digitaltoolsshed.com/calc/cups-to-grams';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyCupsBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '✓ Copied Scale Line to Clipboard!';\n          btn.style.background = '#10b981';\n          btn.style.color = '#fff';\n          setTimeout(function() {\n            btn.innerHTML = orig;\n            btn.style.background = 'var(--surface-alt)';\n            btn.style.color = 'var(--fg)';\n          }, 2200);\n        });\n      }\n\n      document.addEventListener('DOMContentLoaded', calcCupsToGrams);\n      calcCupsToGrams();\n    </script>\n  ";

  writeFileSync(join(calcDir, 'cups-to-grams.html'), renderKitchenPage({
    title: 'Cups to Grams Converter (By Ingredient & Cup Size) | Digital Tools Shed',
    metaDesc: 'Convert cups to grams by ingredient. 1 cup flour = 120g, 1 cup sugar = 200g, 1/2 cup butter = 113.4g. Free digital kitchen scale tare weight calculator.',
    canonical: `${DOMAIN}/calc/cups-to-grams`,
    bodyContent: cupsToGramsBody,
    currentPath: '/calc/cups-to-grams',
    faq: [
      { q: 'How many grams is 1 cup of all-purpose flour?', a: '1 level cup of spooned and leveled all-purpose flour equals 120 grams (4.23 ounces). If dipped and swept directly from the bag, it compacts and can weigh up to 140-155 grams.' },
      { q: 'How many grams is 1/2 cup of granulated sugar?', a: '1/2 cup of granulated white sugar equals exactly 100 grams (3.53 ounces).' },
      { q: 'How many grams is 1 cup of butter (or 1 stick of butter)?', a: '1 cup of butter (which equals 2 American sticks or 16 tablespoons) weighs 227 grams (8.0 ounces). A single stick of butter (1/2 cup or 8 tablespoons) weighs 113.4 grams (4.0 ounces).' },
      { q: 'How many grams is 3/4 cup of brown sugar?', a: '3/4 cup of firmly packed brown sugar weighs 165 grams (5.82 ounces). If measured loose and unpacked, it weighs only approximately 109 grams.' },
      { q: 'How do I convert a recipe from cups to grams if my ingredient is not listed?', a: 'You can determine the grams by multiplying the ingredient\'s bulk density in g/mL by the volume of your measuring cup in milliliters (e.g., 236.6 mL for a US Customary cup). For example, pure water has a density of 1.00 g/mL, yielding 236.6 grams per cup.' }
    ]
  }));

  // ─────────────────────────────────────────────────────────────────────────────
  // 3. BUTTER CONVERTER (STICKS, TBSP, CUPS, OZ, GRAMS)
  // ─────────────────────────────────────────────────────────────────────────────
  const butterBody = "\n    <div class=\"article-container\" style=\"max-width: 950px;\">\n      <nav style=\"font-family: var(--mono); font-size: 0.8rem; margin-bottom: 1.5rem; color: var(--text-muted);\">\n        <a href=\"/\">Home</a> &gt; <a href=\"/calc/\">Calculators</a> &gt; Butter Converter\n      </nav>\n\n      <header style=\"margin-bottom: 2rem;\">\n        <h1 style=\"font-family: var(--serif); font-size: 2.2rem; margin-bottom: 0.5rem;\">Butter Converter (Sticks, Tablespoons, Cups, Grams &amp; Ounces)</h1>\n        <p style=\"color: var(--text-muted); font-size: 1.05rem; line-height: 1.6;\">\n          Convert butter measurements across sticks, tablespoons, cups, ounces, and grams with synchronous bidirectional inputs, European vs. American butterfat calibration, interactive butter stick visualizer, and culinary moisture yield.\n        </p>\n      </header>\n\n      <!-- Golden Rule Banner -->\n      <div style=\"background: var(--surface-alt); border-left: 4px solid var(--border-strong); padding: 0.85rem 1.15rem; margin-bottom: 1.5rem; font-size: 1.05rem; font-family: var(--serif);\">\n        <strong>The Universal American Butter Standard:</strong> 1 Stick = <strong>8 Tablespoons</strong> = <strong>1/2 US Cup</strong> = <strong>4 Ounces (1/4 Pound)</strong> = <strong>113.398 Grams</strong> = <strong>24 Teaspoons</strong>.\n      </div>\n\n      <!-- Synchronous Converter Card -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.25rem;\">\n          <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin: 0; color: var(--fg);\">Multi-Unit Live Converter</h3>\n          <span style=\"font-family: var(--mono); font-size: 0.75rem; color: #10b981; font-weight: bold;\">Synchronous Bidirectional</span>\n        </div>\n\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 1rem; margin-bottom: 1.25rem;\">\n          <div>\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Sticks (US)</label>\n            <input type=\"number\" id=\"butterSticks\" value=\"1\" min=\"0\" step=\"0.125\" class=\"search-input\" style=\"width: 100%; padding: 0.65rem 0.75rem; font-size: 1.2rem; font-family: var(--mono);\" oninput=\"updateFromSticks()\" />\n          </div>\n          <div>\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Tablespoons (Tbsp)</label>\n            <input type=\"number\" id=\"butterTbsp\" value=\"8\" min=\"0\" step=\"0.5\" class=\"search-input\" style=\"width: 100%; padding: 0.65rem 0.75rem; font-size: 1.2rem; font-family: var(--mono);\" oninput=\"updateFromTbsp()\" />\n          </div>\n          <div>\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">US Cups</label>\n            <input type=\"number\" id=\"butterCups\" value=\"0.5\" min=\"0\" step=\"0.0625\" class=\"search-input\" style=\"width: 100%; padding: 0.65rem 0.75rem; font-size: 1.2rem; font-family: var(--mono);\" oninput=\"updateFromCups()\" />\n          </div>\n          <div>\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Grams (g)</label>\n            <input type=\"number\" id=\"butterGrams\" value=\"113.4\" min=\"0\" step=\"0.1\" class=\"search-input\" style=\"width: 100%; padding: 0.65rem 0.75rem; font-size: 1.2rem; font-family: var(--mono); color: #10b981; font-weight: bold;\" oninput=\"updateFromGrams()\" />\n          </div>\n          <div>\n            <label style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); display: block; margin-bottom: 0.35rem; text-transform: uppercase;\">Avoirdupois Ounces (oz)</label>\n            <input type=\"number\" id=\"butterOz\" value=\"4.0\" min=\"0\" step=\"0.05\" class=\"search-input\" style=\"width: 100%; padding: 0.65rem 0.75rem; font-size: 1.2rem; font-family: var(--mono);\" oninput=\"updateFromOz()\" />\n          </div>\n        </div>\n\n        <!-- Butter Type Calibration -->\n        <div style=\"background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; padding: 1rem; margin-bottom: 1.5rem;\">\n          <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.5rem; flex-wrap: wrap; gap: 0.5rem;\">\n            <label style=\"font-family: var(--mono); font-size: 0.8rem; color: var(--fg); font-weight: bold;\">Butter Style &amp; Composition Calibration:</label>\n            <span id=\"butterSpecsBadge\" style=\"font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted);\">80% Fat | 16% Water</span>\n          </div>\n          <select id=\"butterTypeSelect\" onchange=\"recalculateCurrentButter()\" style=\"width: 100%; padding: 0.6rem; background: var(--surface); border: 1px solid var(--border); color: var(--fg); font-family: var(--sans); border-radius: 4px; font-size: 0.9rem;\">\n            <option value=\"80|16.5|0|American Standard (80% Fat, 16.5% Water, Unsalted)\" selected>American Standard (80% Fat, 16.5% Water, Unsalted)</option>\n            <option value=\"80|16.5|1.8|American Salted (80% Fat, 16.5% Water, ~1.8% Salt)\">American Salted (80% Fat, 16.5% Water, ~1.8% Salt)</option>\n            <option value=\"82.5|15.5|0|European Style / Cultured (82.5% Fat, 15.5% Water, e.g. Kerrygold, Plugr&aacute;)\">European Style / Cultured (82.5% Fat, 15.5% Water, e.g. Kerrygold, Plugr&aacute;)</option>\n            <option value=\"99.5|0.3|0|Clarified Butter / Ghee (99.5% Pure Butterfat, 0% Moisture)\">Clarified Butter / Ghee (99.5% Pure Butterfat, 0% Moisture)</option>\n          </select>\n        </div>\n\n        <!-- Pure SVG Butter Stick Visualizer -->\n        <div style=\"background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; padding: 1.25rem; margin-bottom: 1.5rem;\">\n          <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.75rem; flex-wrap: wrap; gap: 0.5rem;\">\n            <h3 style=\"font-family: var(--serif); font-size: 1.1rem; margin: 0; color: var(--fg);\">Interactive 8-Tablespoon Butter Stick Wrapper</h3>\n            <span id=\"svgButterBadge\" style=\"font-family: var(--mono); font-size: 0.75rem; padding: 0.2rem 0.5rem; border-radius: 4px; background: rgba(245,158,11,0.15); color: #d97706; font-weight: bold;\">\n              1.0 Stick (8 Tbsp = 1/2 Cup)\n            </span>\n          </div>\n          <div id=\"butterSvgContainer\" style=\"width: 100%; overflow-x: auto;\">\n            <!-- Rendered by JS -->\n          </div>\n          <div style=\"display: flex; justify-content: space-around; font-family: var(--mono); font-size: 0.75rem; color: var(--text-muted); margin-top: 0.75rem; flex-wrap: wrap; gap: 0.5rem;\">\n            <span><span style=\"display:inline-block; width:10px; height:10px; background:#fbbf24; border-radius:2px; margin-right:4px;\"></span>Active Butter Portion</span>\n            <span><span style=\"display:inline-block; width:10px; height:10px; background:var(--border-strong); border-radius:2px; margin-right:4px;\"></span>Tablespoon Graduation Ticks</span>\n            <span><span style=\"display:inline-block; width:10px; height:10px; background:#10b981; border-radius:2px; margin-right:4px;\"></span>Cut Line Indicator</span>\n          </div>\n        </div>\n\n        <!-- Converted Key Results Grid -->\n        <div id=\"butterResultsGrid\" style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 0.75rem; margin-bottom: 1.5rem;\">\n          <!-- Dynamically populated -->\n        </div>\n\n        <button type=\"button\" id=\"copyButterBtn\" onclick=\"copyButterSummary()\" class=\"btn\" style=\"width: 100%; padding: 0.65rem; font-family: var(--mono); font-size: 0.85rem; font-weight: bold; background: var(--surface-alt); border: 1px solid var(--border); color: var(--fg); border-radius: 4px; cursor: pointer; transition: all 0.2s;\">\n          📋 Copy Butter Recipe Measurement Line\n        </button>\n      </div>\n\n      \n      <!-- 5 Fatal Pitfalls Section -->\n      <div style=\"background: var(--surface); border: 1px solid var(--border); padding: 1.5rem; border-radius: 8px; margin-bottom: 2rem;\">\n        <h3 style=\"font-family: var(--serif); font-size: 1.25rem; margin-top: 0; margin-bottom: 0.75rem; color: var(--fg);\">⚠️ 5 Fatal Butter Conversion Traps & Baking Pitfalls</h3>\n        <p style=\"color: var(--text-muted); font-size: 0.95rem; line-height: 1.6; margin-bottom: 1.25rem;\">\n          Butter is an emulsion of fat, water, and milk solids. Swapping butter types or confusing volume and mass causes collapsed pie crusts, dry cookies, and over-salted pastries:\n        </p>\n\n        <div style=\"display: grid; gap: 1rem;\">\n          <div class=\"trap-card\" style=\"border-left: 4px solid #ef4444;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">1. European (82%–84%) vs. American (80%) Butterfat &amp; Water Disparity</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              American butter is legally required to contain only 80% milkfat, leaving 16% to 18% water. European-style butter (Kerrygold, Plugr&aacute;, President) contains 82% to 84% milkfat and only 14% to 16% water. Substituting American butter into French pastry recipes injects excess water, which activates flour gluten and ruins the delicate lamination of croissants and puff pastry.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #f59e0b;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">2. The Salted vs. Unsalted Sodium Trap</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Commercial salted butter contains between 1.5% and 2.0% salt by weight—equal to approximately <strong>1/3 to 1/2 teaspoon of salt per stick (1.8g to 2.2g)</strong>. If a recipe calls for unsalted butter plus added salt, using salted butter doubles the sodium content, creating an unpleasantly salty profile in sweet frostings and cookies.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #10b981;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">3. East Coast (Elgin) vs. West Coast (Western Pack) Stick Geometry</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Both packages weigh exactly 113.4 grams (1/2 cup), but their shapes differ completely. East Coast \"Elgin\" sticks are long and slender (4.75\" &times; 1.25\"), while West Coast \"Western\" sticks are short and stubby (3.1\" &times; 1.5\"). Measuring butter visually by cutting an inch off the stick will cause a <strong>35% measurement error</strong> if you use the wrong regional pack.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #3b82f6;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">4. Melted Liquid Expansion vs. Cold Solid Emulsion Mass</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              Cold stick butter has a physical bulk density of approximately 0.96 g/mL. When melted, butter expands thermally and separates into clear butterfat (0.89 g/mL) and dense water/milk solids. 1 cup of melted butter poured into a measuring cup yields less total mass than 2 solid sticks packed firmly into the same cup.\n            </p>\n          </div>\n\n          <div class=\"trap-card\" style=\"border-left: 4px solid #8b5cf6;\">\n            <strong style=\"color: var(--fg); font-size: 0.95rem;\">5. The Avoirdupois Dry Ounce vs. Fluid Ounce Confusion</strong>\n            <p style=\"margin: 0.35rem 0 0; font-size: 0.88rem; color: var(--text-muted); line-height: 1.5;\">\n              1 American stick of butter is labeled \"4 oz\" (weight, 113.4 grams), and is simultaneously equal to 1/2 cup (which holds 4 fluid ounces of volume). Because butter's density is very close to water (0.96 vs 1.00), many bakers mistakenly assume dry ounces and fluid ounces are interchangeable across all ingredients, leading to disasters when measuring flour or honey.\n            </p>\n          </div>\n        </div>\n      </div>\n  \n    </div>\n\n    <script>\n      var currentButterGrams = 113.398;\n      var activeInputField = 'sticks';\n\n      function updateFromSticks() {\n        activeInputField = 'sticks';\n        var sticks = parseFloat(document.getElementById('butterSticks').value) || 0;\n        currentButterGrams = sticks * 113.398;\n        syncAllButterInputs('sticks');\n      }\n\n      function updateFromTbsp() {\n        activeInputField = 'tbsp';\n        var tbsp = parseFloat(document.getElementById('butterTbsp').value) || 0;\n        currentButterGrams = (tbsp / 8) * 113.398;\n        syncAllButterInputs('tbsp');\n      }\n\n      function updateFromCups() {\n        activeInputField = 'cups';\n        var cups = parseFloat(document.getElementById('butterCups').value) || 0;\n        currentButterGrams = cups * 2 * 113.398;\n        syncAllButterInputs('cups');\n      }\n\n      function updateFromGrams() {\n        activeInputField = 'grams';\n        var grams = parseFloat(document.getElementById('butterGrams').value) || 0;\n        currentButterGrams = grams;\n        syncAllButterInputs('grams');\n      }\n\n      function updateFromOz() {\n        activeInputField = 'oz';\n        var oz = parseFloat(document.getElementById('butterOz').value) || 0;\n        currentButterGrams = oz * 28.34952;\n        syncAllButterInputs('oz');\n      }\n\n      function recalculateCurrentButter() {\n        syncAllButterInputs(activeInputField);\n      }\n\n      function syncAllButterInputs(source) {\n        var g = currentButterGrams;\n        var sticks = g / 113.398;\n        var tbsp = sticks * 8;\n        var cups = sticks * 0.5;\n        var oz = g / 28.34952;\n        var tsp = tbsp * 3;\n\n        if (source !== 'sticks') document.getElementById('butterSticks').value = sticks.toFixed(3).replace(/\\.?0+$/, '');\n        if (source !== 'tbsp') document.getElementById('butterTbsp').value = tbsp.toFixed(2).replace(/\\.?0+$/, '');\n        if (source !== 'cups') document.getElementById('butterCups').value = cups.toFixed(3).replace(/\\.?0+$/, '');\n        if (source !== 'grams') document.getElementById('butterGrams').value = g.toFixed(1);\n        if (source !== 'oz') document.getElementById('butterOz').value = oz.toFixed(2);\n\n        // Parse butter type\n        var rawType = document.getElementById('butterTypeSelect').value.split('|');\n        var fatPct = parseFloat(rawType[0]);\n        var waterPct = parseFloat(rawType[1]);\n        var saltPct = parseFloat(rawType[2]);\n        var butterName = rawType[3];\n\n        document.getElementById('butterSpecsBadge').textContent = fatPct + '% Fat | ' + waterPct + '% Water' + (saltPct > 0 ? ' | ' + saltPct + '% Salt' : '');\n\n        var fatGrams = g * (fatPct / 100);\n        var waterGrams = g * (waterPct / 100);\n        var calories = fatGrams * 9;\n\n        // Render Results Grid\n        var grid = document.getElementById('butterResultsGrid');\n        grid.innerHTML = \n          '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; text-align: center;\">' +\n            '<span style=\"color: var(--text-muted); font-size: 0.72rem; font-family: var(--mono); text-transform: uppercase;\">Exact Scale Mass</span>' +\n            '<div style=\"font-size: 1.3rem; font-weight: bold; color: #10b981; font-family: var(--mono);\">' + g.toFixed(1) + ' g</div>' +\n            '<span style=\"color: var(--text-muted); font-size: 0.7rem;\">' + oz.toFixed(2) + ' oz</span>' +\n          '</div>' +\n          '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; text-align: center;\">' +\n            '<span style=\"color: var(--text-muted); font-size: 0.72rem; font-family: var(--mono); text-transform: uppercase;\">Tablespoons</span>' +\n            '<div style=\"font-size: 1.3rem; font-weight: bold; color: #3b82f6; font-family: var(--mono);\">' + tbsp.toFixed(1) + ' Tbsp</div>' +\n            '<span style=\"color: var(--text-muted); font-size: 0.7rem;\">' + Math.round(tsp) + ' Teaspoons</span>' +\n          '</div>' +\n          '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; text-align: center;\">' +\n            '<span style=\"color: var(--text-muted); font-size: 0.72rem; font-family: var(--mono); text-transform: uppercase;\">US Recipe Cups</span>' +\n            '<div style=\"font-size: 1.3rem; font-weight: bold; color: var(--fg); font-family: var(--mono);\">' + cups.toFixed(2) + ' Cups</div>' +\n            '<span style=\"color: var(--text-muted); font-size: 0.7rem;\">' + sticks.toFixed(2) + ' Sticks</span>' +\n          '</div>' +\n          '<div style=\"padding: 0.75rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; text-align: center;\">' +\n            '<span style=\"color: var(--text-muted); font-size: 0.72rem; font-family: var(--mono); text-transform: uppercase;\">Pure Milkfat</span>' +\n            '<div style=\"font-size: 1.3rem; font-weight: bold; color: #f59e0b; font-family: var(--mono);\">' + fatGrams.toFixed(1) + ' g</div>' +\n            '<span style=\"color: var(--text-muted); font-size: 0.7rem;\">' + Math.round(calories) + ' kcal</span>' +\n          '</div>';\n\n        // Update SVG\n        document.getElementById('svgButterBadge').textContent = sticks.toFixed(2) + ' Sticks (' + tbsp.toFixed(1) + ' Tbsp | ' + g.toFixed(1) + 'g)';\n        drawButterSvg(sticks, tbsp);\n      }\n\n      function drawButterSvg(sticks, tbsp) {\n        var container = document.getElementById('butterSvgContainer');\n        if (!container) return;\n\n        var startX = 40;\n        var startY = 30;\n        var stickW = 560;\n        var stickH = 45;\n        var tbspW = stickW / 8;\n\n        // Visual fill clamped to 1 stick for ruler representation\n        var visualTbsp = Math.min(8, Math.max(0, tbsp));\n        var fillW = (visualTbsp / 8) * stickW;\n\n        var ticksSvg = '';\n        for (var i = 1; i <= 8; i++) {\n          var tx = startX + (i * tbspW);\n          ticksSvg += \n            '<line x1=\"' + tx + '\" y1=\"' + startY + '\" x2=\"' + tx + '\" y2=\"' + (startY + stickH) + '\" stroke=\"var(--border-strong)\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/>' +\n            '<text x=\"' + (tx - tbspW / 2) + '\" y=\"' + (startY + 28) + '\" fill=\"var(--text-muted)\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"bold\">' + i + ' Tbsp</text>';\n        }\n\n        var svg = \n          '<svg viewBox=\"0 0 640 110\" style=\"width: 100%; height: auto; display: block; font-family: var(--mono);\" xmlns=\"http://www.w3.org/2000/svg\">' +\n            '<!-- Butter Stick Base Frame -->' +\n            '<rect x=\"' + startX + '\" y=\"' + startY + '\" width=\"' + stickW + '\" height=\"' + stickH + '\" rx=\"4\" fill=\"rgba(245,158,11,0.08)\" stroke=\"var(--border-strong)\" stroke-width=\"2\"/>' +\n\n            '<!-- Active Cut Fill (Golden Butter) -->' +\n            '<rect x=\"' + startX + '\" y=\"' + startY + '\" width=\"' + fillW + '\" height=\"' + stickH + '\" rx=\"4\" fill=\"rgba(251,191,36,0.35)\" />' +\n\n            ticksSvg +\n\n            '<!-- Cut Line Indicator -->' +\n            '<line x1=\"' + (startX + fillW) + '\" y1=\"' + (startY - 8) + '\" x2=\"' + (startX + fillW) + '\" y2=\"' + (startY + stickH + 8) + '\" stroke=\"#10b981\" stroke-width=\"3\"/>' +\n            '<polygon points=\"' + (startX + fillW - 5) + ',' + (startY - 8) + ' ' + (startX + fillW + 5) + ',' + (startY - 8) + ' ' + (startX + fillW) + ',' + startY + '\" fill=\"#10b981\"/>' +\n\n            '<!-- Bottom Labels -->' +\n            '<text x=\"' + (startX + tbspW * 2) + '\" y=\"' + (startY + stickH + 22) + '\" fill=\"var(--text-muted)\" font-size=\"9\" text-anchor=\"middle\">1/4 Cup (4 Tbsp)</text>' +\n            '<text x=\"' + (startX + tbspW * 4) + '\" y=\"' + (startY + stickH + 22) + '\" fill=\"var(--text-muted)\" font-size=\"9\" text-anchor=\"middle\">1/2 Cup (8 Tbsp = 1 Stick)</text>' +\n            '<text x=\"' + (startX + fillW) + '\" y=\"' + (startY + stickH + 22) + '\" fill=\"#10b981\" font-size=\"11\" font-weight=\"bold\" text-anchor=\"middle\">Cut Line</text>' +\n          '</svg>';\n\n        container.innerHTML = svg;\n      }\n\n      function copyButterSummary() {\n        var g = currentButterGrams;\n        var sticks = g / 113.398;\n        var tbsp = sticks * 8;\n        var cups = sticks * 0.5;\n        var oz = g / 28.34952;\n        var rawType = document.getElementById('butterTypeSelect').value.split('|');\n        var butterName = rawType[3];\n\n        var text = \n          'BUTTER MEASUREMENT RECIPE LINE\\n' +\n          '========================================\\n' +\n          '• Selected Quantity: ' + sticks.toFixed(2) + ' Sticks of Butter (' + butterName + ')\\n' +\n          '• Tablespoons: ' + tbsp.toFixed(1) + ' Tbsp (' + Math.round(tbsp * 3) + ' tsp)\\n' +\n          '• Volume in Cups: ' + cups.toFixed(2) + ' US Cups\\n' +\n          '• Scale Weight: ' + g.toFixed(1) + ' grams (' + oz.toFixed(2) + ' oz)\\n' +\n          '========================================\\n' +\n          'Calculated via Digital Tools Shed: https://digitaltoolsshed.com/calc/butter-converter';\n\n        navigator.clipboard.writeText(text).then(function() {\n          var btn = document.getElementById('copyButterBtn');\n          var orig = btn.innerHTML;\n          btn.innerHTML = '✓ Copied Butter Recipe Line to Clipboard!';\n          btn.style.background = '#10b981';\n          btn.style.color = '#fff';\n          setTimeout(function() {\n            btn.innerHTML = orig;\n            btn.style.background = 'var(--surface-alt)';\n            btn.style.color = 'var(--fg)';\n          }, 2000);\n        });\n      }\n\n      document.addEventListener('DOMContentLoaded', updateFromSticks);\n      updateFromSticks();\n    </script>\n  ";

  writeFileSync(join(calcDir, 'butter-converter.html'), renderKitchenPage({
    title: 'Butter Converter: Sticks, Tablespoons, Cups, Ounces & Grams | Digital Tools Shed',
    metaDesc: 'Convert butter between sticks, tablespoons, cups, ounces, and grams instantly. Includes European vs. American butterfat moisture calculation, visual wrapper ticks, and 5 fatal baking traps.',
    canonical: `${DOMAIN}/calc/butter-converter`,
    bodyContent: butterBody,
    currentPath: '/calc/butter-converter',
    faq: [
      { q: 'How many tablespoons are in 1 stick of butter?', a: '1 US stick of butter equals exactly 8 tablespoons (which is also 1/2 cup, 4 ounces, or 113.4 grams).' },
      { q: 'How many grams is 1 stick of butter?', a: '1 American stick of butter weighs exactly 113.398 grams (rounded to 113.4g on digital kitchen scales).' },
      { q: 'How many sticks of butter make 1 cup?', a: '2 sticks of butter make 1 full cup (16 tablespoons or 226.8 grams).' },
      { q: 'Why do European recipes require less butter than American recipes?', a: 'European butter has higher butterfat (82%–84%) and less water (14%–16%) than American butter (80% fat, 16%–18% water). When making flaky croissants or pie dough, European butter yields crisper layers because less steam toughens the gluten.' },
      { q: 'How much salt is in salted butter?', a: 'Commercial salted butter contains roughly 1.5% to 2.0% salt by weight, which is equal to approximately 1/3 to 1/2 teaspoon of salt per stick (1.8g to 2.2g).' }
    ]
  }));

  console.log('  ✓ Built Kitchen Suite (grams-to-cups, cups-to-grams, butter-converter in /calc/)');
}
